34	public abstract class NonPrimitive extends Simple_fcn {
35	
36	    static final List<FValue> VOID_ARG = Collections.singletonList((FValue) FVoid.V);
37	
38	    /*
39	     * (non-Javadoc)
40	     *
41	     * @see com.sun.fortress.interpreter.evaluator.values.Simple_fcn#at()
42	     */
43	    @Override
44	    public String at() {
45	        return getAt().at();
46	    }
47	
48	    protected abstract HasAt getAt();
49	
50	    NonPrimitive(Environment within) {
51	        super(within);
52	    }
53	
54	    private List<Parameter> params;
55	
56	    private boolean lastParamIsRest;
57	
58	    private volatile List<FType> cachedDomain;
59	
60	    protected boolean hasRest() {
61	        return lastParamIsRest;
62	    }
63	
64	    /**
65	     * @param params The params to set.
66	     */
67	    public final void setParams(List<Parameter> original_params) {
68	
69	        List<Parameter> params = adjustParameterList(original_params);
70	
71	        if (this.params != null) {
72	            if (!this.params.equals(params)) bug(this.getAt(), errorMsg(
73	                    "Attempted second set of constructor/function/method params of ",
74	                    this,
75	                    " to ",
76	                    Useful.listInParens(original_params)));
77	            // be idempotent
78	            return;
79	        }
80	
81	        this.params = params;
82	        lastParamIsRest = params.size() > 0 && (params.get(params.size() - 1).getType() instanceof FTypeRest);
83	        setValueType();
84	    }
85	
86	    protected List<Parameter> adjustParameterList(List<Parameter> params2) {
87	        return params2;
88	    }
89	
90	    abstract protected void setValueType();
91	
92	    /**
93	     * @return Returns the params.
94	     */
95	    public List<Parameter> getParameters() {
96	        if (params == null) return bug(getAt(), errorMsg("getParams of NonPrimitive ", this));
97	        return params;
98	    }
99	
100	    @Override
101	    public List<FType> getDomain() {
102	        if (cachedDomain == null) {
103	            synchronized (this) {
104	                if (cachedDomain == null) {
105	                    //                    if (this instanceof FunctionalMethod
106	                    //                            && ((FunctionalMethod) this).getSelfParameterType()
107	                    //                                    .toString().contains("ParRange"))
108	                    //                        System.err.println("getDomain of " + this);
109	                    List<FType> l = typeListFromParameters(getParameters());
110	                    cachedDomain = l;
111	                }
112	            }
113	        }
114	        return cachedDomain;
115	    }
116	
117	    public static List<FValue> stripAsIf(List<FValue> args) {
118	        List<FValue> res = new ArrayList<FValue>(args.size());
119	        for (FValue v : args) {
120	            if (v instanceof FAsIf) {
121	                res.add(((FAsIf) v).getValue());
122	            } else {
123	                res.add(v);
124	            }
125	        }
126	        return res;
127	    }
128	
129	    /**
130	     * Take passed-in parameters, type check them.
131	     * Intended to be called from NativeApp.
132	     * Do not bother calling this if you also call buildEnvFromParams.
133	     */
134	    public List<FValue> typecheckParams(List<FValue> args) {
135	        args = fixupArgCount(args);
136	        List<FValue> coerced = null;   // args with any converted argument in place
137	        Iterator<FValue> argsIter = args.iterator();
138	        Iterator<Parameter> paramsIter = params.iterator();
139	        boolean asif = false;   // Need to strip asif?  Avoid if not.
140	        for (int i = 1; paramsIter.hasNext(); i++) {
141	            Parameter param = paramsIter.next();
142	            FType paramType = param.getType();
143	            if (paramType instanceof FTypeRest) {
144	                FType restType = ((FTypeRest) paramType).getType();
145	                for (; argsIter.hasNext(); i++) {
146	                    FValue arg = argsIter.next();
147	                    if (arg instanceof FAsIf) asif = true;
148	                    if (!restType.typeMatch(arg)) {
149	                        FValue c = Coercions.coerce(restType, arg);
150	                        if (c != null) {
151	                            if (coerced == null) coerced = new ArrayList<FValue>(args);
152	                            coerced.set(i - 1, c);
153	                            continue;
154	                        }
155	                        error(errorMsg("Closure/Constructor for ",
156	                                       getAt().stringName(),
157	                                       " rest parameter ",
158	                                       i,
159	                                       " (",
160	                                       param.getName(),
161	                                       ":",
162	                                       restType,
163	                                       "...) got type ",
164	                                       arg.type()));
165	                    }
166	                }
167	            } else {
168	                // Usual case for the loop.
169	                FValue arg = argsIter.next();
170	                if (arg instanceof FAsIf) asif = true;
171	                if (!paramType.typeMatch(arg)) {
172	                    FValue c = Coercions.coerce(paramType, arg);
173	                    if (c != null) {
174	                        if (coerced == null) coerced = new ArrayList<FValue>(args);
175	                        coerced.set(i - 1, c);
176	                        continue;
177	                    }
178	                    error(errorMsg("Closure/Constructor for ",
179	                                   getAt().stringName(),
180	                                   " parameter ",
181	                                   i,
182	                                   " (",
183	                                   param.getName(),
184	                                   ":",
185	                                   param.getType(),
186	                                   ") got type ",
187	                                   arg.type()));
188	                }
189	            }
190	        }
191	        if (coerced != null) args = coerced;
192	        if (asif) return stripAsIf(args);
193	        else return args;
194	    }
195	
196	    /**
197	     * Build environment for evaluation of closure.
198	     * Intended to be called from Closure.
199	     *
200	     * @throws Error
201	     */
202	    public Environment buildEnvFromParams(List<FValue> args) throws Error {
203	        Environment env = within.extendAt(getAt());
204	        return buildEnvFromParams(args, env);
205	    }
