207	    public Environment buildEnvFromEnvAndParams(Environment env, List<FValue> args) throws Error {
208	        env = env.extendAt(getAt());
209	        return buildEnvFromParams(args, env);
210	    }
211	
212	    private Environment buildEnvFromParams(List<FValue> args, Environment env) throws Error {
213	        // TODO Here is where we deal with rest parameters.
214	        List<FValue> argsTemp = fixupArgCount(args);
215	        if (argsTemp == null) return bug(
216	                "The number of parameters (" + params.size() + ") does not match with the number of arguments (" +
217	                args.size() + ").");
218	        args = argsTemp;
219	        Iterator<FValue> argsIter = args.iterator();
220	        FValue arg = null;
221	        int i = 0;
222	        for (Parameter param : params) {
223	            FType paramType = param.getType();
224	            if (paramType instanceof FTypeRest) {
225	                // Finish processing args in here (we just saw the last
226	                // parameter)
227	
228	                // Find and invoke array1[\ T, size1 \] ()
229	                String genericName = WellKnownNames.varargsFactoryName;
230	                int[] natParams = new int[1];
231	                natParams[0] = args.size() - i;
232	
233	                Environment wknInstantiationEnv = Driver.getFortressLibrary();
234	
235	                Simple_fcn f = Glue.instantiateGenericConstructor(wknInstantiationEnv,
236	                                                                  genericName,
237	                                                                  ((FTypeRest) paramType).getType(),
238	                                                                  natParams);
239	
240	                FValue theArray = f.applyToArgs();
241	                if (!(theArray instanceof FObject)) return bug(errorMsg(f, " returned non-FObject ", theArray));
242	                // Use a wrapper to simplify our life
243	                IndexedArrayWrapper iaw = new IndexedArrayWrapper(theArray);
244	                int j = 0;
245	                while (argsIter.hasNext()) {
246	                    arg = argsIter.next();
247	                    iaw.put(arg.getValue(), j);  // strip asif
248	                    j++;
249	                }
250	                // Do the copy.
251	                env.putValue(param.getName(), theArray);
252	            } else {
253	                // Usual case for the loop.
254	                arg = argsIter.next();
255	                i++;
256	                if (!paramType.typeMatch(arg)) {
257	                    FValue c = Coercions.coerce(paramType, arg);
258	                    if (c == null) unificationError(errorMsg("Closure/Constructor for ",
259	                                              getAt().stringName(),
260	                                              " param ",
261	                                              i,
262	                                              " (",
263	                                              param.getName(),
264	                                              ":",
265	                                              paramType,
266	                                              ") got arg ",
267	                                              arg,
268	                                              " of type ",
269	                                              arg.type()));
270	                    arg = c;
271	                }
272	                arg = arg.getValue(); // Strip asif
273	                try {
274	                    if (param.getMutable()) {
275	                        env.putValueRaw(param.getName(), arg, param.getType());
276	                    } else {
277	                        env.putValueRaw(param.getName(), arg);
278	                    }
279	                }
280	                catch (FortressException ex) {
281	                    throw ex.setWithin(env);
282	                }
283	            }
284	
285	        }
286	        return env;
287	    }
288	
289	    /**
290	     * Return fixed up arguments; throws ProgramError if different lengths.
291	     */
292	    public List<FValue> fixupArgCount(List<FValue> args0, HasAt loc) {
293	        List<FValue> args = fixupArgCount(args0);
294	        if (args == null) {
295	            error(loc, errorMsg("Incorrect number of arguments, expected ",
296	                                Useful.listInParens(params),
297	                                ", got ",
298	                                Useful.listInParens(args0)));
299	        }
300	        return args;
301	    }
302	
303	    /**
304	     * @param args
305	     * @return fixed up arguments, or null if different lengths.
306	     */
307	    public List<FValue> fixupArgCount(List<FValue> args) {
308	        if (this.params == null) {
309	            bug(this.getAt(), "Calling fixupArgCount on " + getAt().stringName() + " with null params");
310	        }
311	        if (args.size() == params.size()) return args;
312	        if (hasRest() && args.size() + 1 >= params.size()) {
313	            return args;
314	        }
315	        if (params.size() == 1) {
316	            /* Obscure screw case: a type parameter was instantiated
317	             * with void / tuple, or we declared a single parameter of
318	             * void or tuple type ().  This is satisfied by a 0-ary
319	             * application.  Rather than checking thoroughly, we
320	             * return a singleton void and let the enclosing test
321	             * catch it. */
322	            if (args.size() == 0) return VOID_ARG;
323	            return Collections.singletonList((FValue) FTuple.make(args));
324	        }
325	        return null;
326	    }
327	}
