50	        if (!isTraitMethod) {
51	            cl = new MethodClosureInstance(getEnv(), clenv, getDef(), getDefiner(), args, this);
52	        } else if (FType.anyAreSymbolic(args)) {
53	            cl = new TraitMethodInstance(getEnv(), clenv, getDef(), getDefiner(), args, this);
54	        } else {
55	            // TODO Intention is that this is a plain old instantiation,
56	            // however there are issues of capturing the evaluation
57	            // environment that makes this not work quite right
58	            // MethodClosureInstance ought to be MethodClosure, but
59	            // isn't, yet.
60	            cl = new TraitMethod(getEnv(), clenv, getDef(), getDefiner(), args);
61	        }
62	        cl.finishInitializing();
63	        return (MethodClosure) cl;
64	    }
