26	/**
27	 * A DottedMethodApplication is produced when a FieldRef occurs in
28	 * a loosely juxtaposed context.  It simply packages up self along with
29	 * with the method closure, permitting them to be applied to arguments
30	 * as if they were an ordinary function closure.
31	 */
32	public final class DottedMethodApplication extends Fcn {
33	
34	    private final Method cl;
35	    private final FObject self;
36	
37	    private DottedMethodApplication(FObject self, Method cl, Environment selfEnv) {
38	        super(selfEnv);
39	        this.cl = cl;
40	        this.self = self;
41	    }
42	
43	    /**
44	     * This factory does the work necessary to deal with AsIf
45	     * receivers, and the DottedMethodApplication the results
46	     * packages up the required information that results (most
47	     * importantly the receiver, self, and the method closure cl).
48	     * It has been written in a fairly general way in order to permit
49	     * it to represent arbitrary method applications encountered
50	     * during Evaluation.
51	     */
52	    public static DottedMethodApplication make(FValue receiver, String prettyName, String mname) {
53	        // Step 1: determine self (modulo AsIf), make sure it's an object,
54	        //    and simultaneously determine the selfEnv for errors.
55	        // TODO Need to distinguish between public/private
56	        // methods/fields
57	        //  (actually this is properly the duty of static analysis).
58	        Environment selfEnv;
59	        FObject self;
60	        FValue cl;
61	        if (receiver instanceof FObject) {
62	            self = (FObject) receiver;
63	            selfEnv = self.getSelfEnv();
64	            cl = selfEnv.getLeafValueNull(mname); // leaf
65	        } else {
66	            // fobj instanceof FAsIf, nontrivial type().  Since
67	            // getMembers() on traits only returns the immediately
68	            // defined methods and fields, we need to walk the
69	            // transitive extends hierarchy in order to find the
70	            // method we're looking for.  Open question: Is this right
71	            // or sufficient?  What happens if multiple overloadings
72	            // of given method are obtained from different
73	            // supertraits---will we actually get an overloaded method
74	            // closure, or will the world simply break?
75	
76	            FValue selfVal = receiver.getValue();
77	            if (!(selfVal instanceof FObject)) {
78	                return error(errorMsg("Non-object receiver ", receiver, " trying to invoke method ", prettyName));
79	            }
80	            self = (FObject) selfVal;
81	            FType rtype = receiver.type();
82	            if (rtype instanceof FTypeTrait) {
83	                cl = null;
84	                selfEnv = null;
85	                FTypeTrait tr = (FTypeTrait) rtype;
86	                for (FType t : tr.getTransitiveExtends()) {
87	                    if (!(t instanceof FTypeTrait)) continue;
88	                    selfEnv = ((FTypeTrait) t).getMembers();
89	                    cl = selfEnv.getLeafValueNull(mname); // leaf
90	                    if (cl != null) break;
91	                }
92	                if (cl == null) {
93	                    // We're going to fail; set selfEnv to root of search.
94	                    selfEnv = tr.getMembers();
95	                }
96	            } else {
97	                selfEnv = self.getSelfEnv();
