396	            String n = NodeUtil.getName(tp);
397	            if (!NodeUtil.isTypeParam(tp) || fixed.contains(n) || !rechecks.contains(tp) ||
398	                !(tl.get(i) instanceof BottomType)) continue;
399	            FType b = boundAtInstances(tp, tparams, tl, appliedThing);
400	            if (b != null) {
401	                traceInstance("unfixed", appliedThing, n, BottomType.ONLY, b, typesOf(args));
402	                tl.set(i, b);
403	            }
404	        }
405	        return tl;
406	    }
