408	    /**
409	     * The type parameters of typeParams that the declared types of params
410	     * mention only where an argument bounds them from above, as the domain of
411	     * a function type does: in an odd number of arrow domains, and never as
412	     * a static argument of a type.
413	     */
414	    private static Set<String> boundedOnlyAbove(List<Param> params, Set<String> typeParams) {
415	        Set<String> above = new HashSet<String>();
416	        Set<String> below = new HashSet<String>();
417	        for (Param p : params) {
418	            Type ty;
419	            if (NodeUtil.isVarargsParam(p)) ty = p.getVarargsType().unwrap();
420	            else if (p.getIdType().isSome()) ty = NodeUtil.optTypeOrPatternToType(p.getIdType()).unwrap();
421	            else continue;
422	            polarities(ty, true, typeParams, below, above);
423	        }
424	        above.removeAll(below);
425	        return above;
426	    }
