428	    /**
429	     * Files each name of names that ty mentions under below where an argument
430	     * of type ty bounds it from below (positive) and under above where it
431	     * bounds it from above; a mention inside a static argument goes under
432	     * both.
433	     */
434	    private static void polarities(Type ty, boolean positive, Set<String> names, Set<String> below,
435	                                   Set<String> above) {
436	        if (ty instanceof VarType) {
437	            String n = NodeUtil.nameString(((VarType) ty).getName());
438	            if (names.contains(n)) (positive ? below : above).add(n);
439	        } else if (ty instanceof ArrowType) {
440	            polarities(((ArrowType) ty).getRange(), positive, names, below, above);
441	            polarities(((ArrowType) ty).getDomain(), !positive, names, below, above);
442	        } else if (ty instanceof TupleType) {
443	            TupleType tt = (TupleType) ty;
444	            for (Type e : tt.getElements()) polarities(e, positive, names, below, above);
445	            if (tt.getVarargs().isSome()) polarities(tt.getVarargs().unwrap(), positive, names, below, above);
446	            for (KeywordType k : tt.getKeywords()) polarities(k.getKeywordType(), positive, names, below, above);
447	        } else {
448	            Set<String> m = mentions(ty, names);
449	            below.addAll(m);
450	            above.addAll(m);
451	        }
452	    }
