454	    /**
455	     * The static parameters of tparams named in fixable, and those that a
456	     * bound of one of them mentions, as A extends T mentions T.
457	     */
458	    private static Set<String> fixedThroughBounds(List<StaticParam> tparams, Set<String> fixable) {
459	        Set<String> names = new HashSet<String>();
460	        for (StaticParam tp : tparams) names.add(NodeUtil.getName(tp));
461	        Set<String> fixed = new HashSet<String>(fixable);
462	        boolean grew = true;
463	        while (grew) {
464	            grew = false;
465	            for (StaticParam tp : tparams) {
466	                if (!fixed.contains(NodeUtil.getName(tp))) continue;
467	                for (Type tr : tp.getExtendsClause()) {
468	                    for (String m : mentions(tr, names)) grew |= fixed.add(m);
469	                }
470	            }
471	        }
472	        return fixed;
473	    }
