475	    /**
476	     * The meet of the bounds of the type parameter tp of g at the instances
477	     * tl of the static parameters they mention; null where they mention tp
478	     * itself or a static parameter whose instance is BottomType, or where
479	     * they cannot be evaluated.
480	     */
481	    private static FType boundAtInstances(StaticParam tp, List<StaticParam> tparams, List<FType> tl,
482	                                          GenericFunctionOrMethod g) {
483	        Map<String, FType> inst = new HashMap<String, FType>();
484	        for (int i = 0; i < tparams.size(); i++) inst.put(NodeUtil.getName(tparams.get(i)), tl.get(i));
485	        for (Type tr : tp.getExtendsClause()) {
486	            for (String m : mentions(tr, inst.keySet())) {
487	                if (m.equals(NodeUtil.getName(tp)) || inst.get(m) instanceof BottomType) return null;
488	            }
489	        }
490	        try {
491	            Environment env = g.getWithin().extendAt(tp);
492	            EvalType.bindGenericParameters(tparams, tl, env, tp, tp);
493	            EvalType et = new EvalType(env);
494	            FType b = null;
495	            for (Type tr : tp.getExtendsClause()) {
496	                FType t = et.evalType(tr);
497	                b = b == null ? t : TypeLatticeOps.V.meet(b, t);
498	            }
499	            return b;
500	        }
501	        catch (FortressException ex) {
502	            return null;
503	        }
504	    }
