506	    /**
507	     * An instantiation of a generic function that admits every argument by
508	     * subtyping or by one coercion, or null.  An argument whose declared type
509	     * mentions a static parameter other than as the whole type is unified with
510	     * it; an argument whose declared type mentions no static parameter is left
511	     * to the coercion at binding; a type parameter that is the whole declared
512	     * type of some argument and that nothing else fixes takes the narrowest of
513	     * its arguments' types, the types they coerce to and its bounds that each
514	     * of those arguments is a subtype of or coerces to, and, when no one is
515	     * narrowest, its bound, where each of those arguments is a subtype of it;
516	     * one whose bound mentions a static parameter takes the narrowest of those
517	     * and of the arguments' supertypes, and otherwise the join of its
518	     * arguments' types.  A type parameter that no argument fixes takes its
519	     * bound (instanceOf).
520	     */
521	    private static Simple_fcn inferWithCoercion(List<FValue> args,
522	                                                GenericFunctionOrMethod appliedThing,
523	                                                Environment envForInference, BigOperatorHint h) {
524	        try {
525	            return inferWithCoercionOrFail(args, appliedThing, envForInference, h);
526	        }
527	        catch (FortressException ex) {
528	            return null;
529	        }
530	        catch (EmptyLatticeIntervalError ex) {
531	            return null;
532	        }
533	    }
