535	    private static Simple_fcn inferWithCoercionOrFail(List<FValue> args,
536	                                                      GenericFunctionOrMethod appliedThing,
537	                                                      Environment envForInference, BigOperatorHint h) {
538	        final List<FValue> originalArgs = args;
539	        GenericTypeInstance selfType = null;
540	        if (appliedThing instanceof GenericFunctionalMethod) {
541	            GenericFunctionalMethod gfm = (GenericFunctionalMethod) appliedThing;
542	            FTypeGeneric declaredSelfType = gfm.getSelfParameterTypeAsGeneric();
543	            FValue selfArg = args.get(gfm.getSelfParameterIndex());
544	            if (!(selfArg.type() instanceof GenericTypeInstance)) return null;
545	            selfType = (GenericTypeInstance) selfArg.type();
546	            for (FType ft : selfType.getTransitiveExtends()) {
547	                if (ft instanceof GenericTypeInstance && ((GenericTypeInstance) ft).getGeneric().equals(
548	                        declaredSelfType)) {
549	                    selfType = (GenericTypeInstance) ft;
550	                    break;
551	                }
552	            }
553	            envForInference = selfType.getWithin();
554	        }
555	        List<StaticParam> tparams = appliedThing.getStaticParams();
556	        List<Param> params = appliedThing.getParams();
557	        EvalType et = new EvalType(appliedThing.getWithin());
558	        BoundingIntervals abm = new BoundingIntervals(true);
559	        Set<String> tp_set = new HashSet<String>();
560	        Set<String> typeParams = new HashSet<String>();
561	        Map<String, List<FType>> bounds = new HashMap<String, List<FType>>();
562	        List<StaticParam> rechecks = new ArrayList<StaticParam>();
563	        for (StaticParam sp : tparams) {
564	            String name = NodeUtil.getName(sp);
565	            tp_set.add(name);
566	            if (!NodeUtil.isTypeParam(sp)) continue;
567	            typeParams.add(name);
568	            List<FType> bs = new ArrayList<FType>();
569	            bounds.put(name, bs);
570	            for (Type tr : sp.getExtendsClause()) {
571	                try {
572	                    FType tt = et.evalType(tr);
573	                    abm.meetPut(name, tt);
574	                    bs.add(tt);
575	                }
576	                catch (FortressException pe) {
577	                    if (!rechecks.contains(sp)) rechecks.add(sp);
578	                }
579	            }
580	        }
581	        if (params.size() == 1 && args.size() != 1 && !NodeUtil.isVarargsParam(params.get(0))) {
582	            args = Useful.<FValue>list(FTuple.make(args));
583	        }
584	        /* The first pass: the arguments whose declared type is not a type parameter alone. */
585	        Map<String, List<FValue>> lone = new LinkedHashMap<String, List<FValue>>();
586	        Map<String, Type> loneType = new HashMap<String, Type>();
587	        Set<String> fixedElsewhere = new HashSet<String>();
588	        Iterator<Param> pit = params.iterator();
589	        Param p = null;
590	        for (FValue a : args) {
591	            FType at = a.type();
592	            if (at == null) return null;
593	            if (pit.hasNext()) p = pit.next();
594	            else if (p == null) return null;
595	            if (NodeUtil.isVarargsParam(p)) {
596	                Type ty = p.getVarargsType().unwrap();
597	                fixedElsewhere.addAll(mentions(ty, tp_set));
598	                at.unify(envForInference, tp_set, abm, ty);
599	                continue;
600	            }
601	            Option<TypeOrPattern> t = p.getIdType();
602	            if (t.isNone()) {
603	                boolean isSelf = p.getName().toString().equals("self");
604	                if (isSelf && appliedThing instanceof GenericFunctionalMethod.Own) continue;
605	                if (!(isSelf && appliedThing instanceof GenericFunctionalMethod)) {
606	                    return null;
607	                }
608	                Type selfInst = selfType.getGeneric().getInstantiationForFunctionalMethodInference();
609	                at.unify(envForInference, tp_set, abm, selfInst);
610	                fixedElsewhere.addAll(mentions(selfInst, tp_set));
611	                continue;
612	            }
613	            Type ty = NodeUtil.optTypeOrPatternToType(t).unwrap();
614	            if (ty instanceof VarType && typeParams.contains(NodeUtil.nameString(((VarType) ty).getName()))) {
615	                String n = NodeUtil.nameString(((VarType) ty).getName());
616	                if (!lone.containsKey(n)) {
617	                    lone.put(n, new ArrayList<FValue>());
618	                    loneType.put(n, ty);
619	                }
620	                lone.get(n).add(a);
621	                continue;
622	            }
623	            Set<String> m = mentions(ty, tp_set);
624	            if (m.isEmpty()) continue;
625	            fixedElsewhere.addAll(m);
626	            at.unify(envForInference, tp_set, abm, ty);
627	        }
628	        /* The second pass: each type parameter that stands alone and that the first pass did not fix. */
629	        for (Map.Entry<String, List<FValue>> e : lone.entrySet()) {
630	            String n = e.getKey();
631	            FType fixed = abm.get(n);
632	            if (fixedElsewhere.contains(n) && fixed != null && !(fixed instanceof BottomType)) continue;
633	            boolean selfBounded = selfBounded(n, rechecks);
634	            FType chosen = narrowest(n, e.getValue(), abm, rechecks, tp_set, envForInference, bounds.get(n),
635	                                     appliedThing.getWithin(), selfBounded);
636	            FType bound = boundOf(abm, n);
637	            if (chosen == null && !selfBounded && allSubtypes(e.getValue(), bound)) chosen = bound;
638	            if (TRACE != null && !selfBounded) {
639	                FType before = narrowest(n, e.getValue(), abm, rechecks, tp_set, envForInference, bounds.get(n),
640	                                         appliedThing.getWithin(), true);
641	                if (before == null || !before.equals(chosen)) {
642	                    traceInstance("lone", appliedThing, n, before == null ? "join" : before, chosen,
643	                                  typesOf(e.getValue()));
644	                }
645	            }
646	            if (chosen != null) {
647	                abm.joinPut(n, chosen);
648	            } else {
649	                for (FValue a : e.getValue()) a.type().unify(envForInference, tp_set, abm, loneType.get(n));
650	            }
651	        }
652	        /* A big operator under a hint: the declared type first, unified with the result type O of the
653	           declared result, and else the elements' join, unified with its element type I; each on a
654	           trial copy first, so that a hint that does not fit leaves the inference as it was. */
655	        boolean byExpected = false;
656	        if (h != null && h.expected != null) {
657	            Type ot = resultArgOf(appliedThing, true);
658	            if (ot != null) {
659	                try {
660	                    h.expected.unify(envForInference, tp_set, abm.copy(), ot);
661	                    h.expected.unify(envForInference, tp_set, abm, ot);
662	                    fixedElsewhere.addAll(mentions(ot, tp_set));
663	                    byExpected = true;
664	                    traceInstance("expected", appliedThing, String.valueOf(ot), BottomType.ONLY, h.expected, "");
665	                }
666	                catch (FortressException ex) {
667	                    // the elements' type, or the bound
668	                }
669	            }
670	        }
671	        if (h != null && !byExpected && h.elements != null) {
672	            Type it = resultArgOf(appliedThing, false);
673	            if (it != null) {
674	                try {
675	                    h.elements.unify(envForInference, tp_set, abm.copy(), it);
676	                    h.elements.unify(envForInference, tp_set, abm, it);
677	                    fixedElsewhere.addAll(mentions(it, tp_set));
678	                    traceInstance("elements", appliedThing, String.valueOf(it), BottomType.ONLY, h.elements, "");
679	                }
680	                catch (FortressException ex) {
681	                    // the bound, as where no element is given
682	                }
683	            }
684	        }
685	        MakeInferenceSpecific mis = new MakeInferenceSpecific(abm);
686	        Option<Type> opt_rt = appliedThing.getReturnType();
687	        if (opt_rt.isSome()) opt_rt.unwrap().accept(mis);
688	        for (StaticParam tp : rechecks) {
689	            FType t = abm.get(NodeUtil.getName(tp));
690	            if (t == null) t = BottomType.ONLY;
691	            for (Type tr : tp.getExtendsClause()) t.unify(envForInference, tp_set, abm, tr);
692	        }
693	        Set<String> fixable = new HashSet<String>(fixedElsewhere);
694	        fixable.addAll(lone.keySet());
695	        ArrayList<FType> tl = instanceOf(tparams, abm, fixable, boundedOnlyAbove(params, typeParams), rechecks, true,
696	                                         appliedThing, originalArgs);
697	        Simple_fcn sfcn = appliedThing.typeApply(tl);
698	        /* Every argument admitted by the instance's domain, by subtyping or by one coercion. */
699	        List<FValue> fargs = sfcn.fixupArgCount(originalArgs);
700	        if (fargs == null) return null;
701	        List<FType> dom = sfcn.getDomain();
702	        for (int j = 0; j < fargs.size(); j++) {
703	            if (!Coercions.admits(Useful.clampedGet(dom, j).deRest(), fargs.get(j))) return null;
704	        }
705	        if (byExpected) h.byExpected = true;
706	        return sfcn;
707	    }
