759	    /**
760	     * The narrowest type for the type parameter n whose arguments are vals, or
761	     * null: among the arguments' types, the types they coerce to and n's
762	     * bounds, and with supertypes the arguments' supertypes as well, those
763	     * that each argument is a subtype of or coerces to and that n's bounds
764	     * admit, the one that is a subtype of every other or coerces to it.
765	     */
766	    private static FType narrowest(String n, List<FValue> vals,
767	                                   BoundingMap<String, FType, TypeLatticeOps> abm,
768	                                   List<StaticParam> rechecks, Set<String> tp_set, Environment env,
769	                                   List<FType> bounds, Environment within, boolean supertypes) {
770	        LinkedHashSet<FType> candidates = new LinkedHashSet<FType>();
771	        for (FValue v : vals) {
772	            if (supertypes) candidates.addAll(v.type().getTransitiveExtends());
773	            else candidates.add(v.type());
774	        }
775	        for (FValue v : vals) candidates.addAll(Coercions.coercionTargets(v, within));
776	        if (bounds != null) candidates.addAll(bounds);
777	        List<FType> admitted = new ArrayList<FType>();
778	        for (FType c : candidates) {
779	            if (c instanceof BottomType || c instanceof FTypeTop) continue;
780	            boolean all = true;
781	            for (FValue v : vals) {
782	                if (!Coercions.admits(c, v)) {
783	                    all = false;
784	                    break;
785	                }
786	            }
787	            if (!all) continue;
788	            BoundingMap<String, FType, TypeLatticeOps> trial = abm.copy();
789	            try {
790	                trial.joinPut(n, c);
791	                for (StaticParam tp : rechecks) {
792	                    if (!NodeUtil.getName(tp).equals(n)) continue;
793	                    for (Type tr : tp.getExtendsClause()) c.unify(env, tp_set, trial, tr);
794	                }
795	            }
796	            catch (FortressException ex) {
797	                continue;
798	            }
799	            catch (EmptyLatticeIntervalError ex) {
800	                continue;
801	            }
802	            admitted.add(c);
803	        }
804	        FType best = null;
805	        for (FType c : admitted) {
806	            boolean narrower = true;
807	            for (FType d : admitted) {
808	                if (d != c && !c.subtypeOf(d) && !Coercions.convertsInto(c, d)) {
809	                    narrower = false;
810	                    break;
811	                }
812	            }
813	            if (narrower) {
814	                if (best != null && best != c) return null;
815	                best = c;
816	            }
817	        }
818	        return best;
819	    }
