833	    /**
834	     * With bounded, a type parameter that no argument fixes and whose bounds
835	     * mention no static parameter takes its bound, as in inferWithCoercion;
836	     * without, it is BottomType, which is how a declaration is chosen.
837	     */
838	    private static Simple_fcn inferByUnification(List<FValue> args,
839	                                                 GenericFunctionOrMethod appliedThing,
840	                                                 Environment envForInference,
841	                                                 boolean bounded) throws ProgramError {
842	
843	        if (DUMP_INFERENCE) System.err.println("IAIGF " + appliedThing + " with " + args);
844	        final List<FValue> originalArgs = args;
845	
846	        GenericTypeInstance selfType = null; // initialized if generic functional method
847	
848	        if (appliedThing instanceof GenericFunctionalMethod) {
849	            GenericFunctionalMethod gfm = (GenericFunctionalMethod) appliedThing;
850	            int spi = gfm.getSelfParameterIndex();
851	            FTypeGeneric declaredSelfType = gfm.getSelfParameterTypeAsGeneric();
852	            FValue selfArg = args.get(spi);
853	
854	            if (selfArg.type() instanceof GenericTypeInstance) {
855	                selfType = (GenericTypeInstance) selfArg.type();
856	                // Find the supertype that exactly matches "self"
857	                for (FType ft : selfType.getTransitiveExtends()) {
858	                    if (ft instanceof GenericTypeInstance && ((GenericTypeInstance) ft).getGeneric().equals(
859	                            declaredSelfType)) {
860	                        selfType = (GenericTypeInstance) ft;
861	                        break;
862	                    }
863	                }
864	                envForInference = selfType.getWithin();
865	            } else return error(errorMsg("Non-generic-instance type for self argument ",
866	                                         selfArg,
867	                                         " to generic functional method ",
868	                                         appliedThing));
869	        }
870	
871	        List<StaticParam> tparams = appliedThing.getStaticParams();
872	        List<Param> params = appliedThing.getParams();
873	        // Must use the right environment for unifying against the generic.
874	        // It was "e", which is wrong.
875	        EvalType et = new EvalType(appliedThing.getWithin());// e);
876	        // The types of the actual parameters ought to unify with the
877	        // types of the formal parameters.
878	        BoundingIntervals abm = new BoundingIntervals(bounded);
879	        Set<String> fixable = new HashSet<String>();
880	        Param p = null;
881	        Set<String> tp_set = new HashSet<String>();
882	        List<StaticParam> rechecks = null;
883	        for (StaticParam sp : tparams) {
884	            boolean rechecked = false;
885	            String name = NodeUtil.getName(sp);
886	            tp_set.add(name);
887	            if (NodeUtil.isTypeParam(sp)) {
888	                if (DUMP_INFERENCE) System.err.println("TypeParam " + sp);
889	                for (Type tr : sp.getExtendsClause()) {
890	                    // Preinstall bounds in the boundingmap
891	                    try {
892	                        FType tt = et.evalType(tr);
893	                        if (DUMP_INFERENCE) System.err.println("    extends " + tr + " = " + tt);
894	                        abm.meetPut(name, tt);
895	                    }
896	                    catch (FortressException pe) {
897	                        if (DUMP_INFERENCE) System.err.println("    extends with failed evalType " + tr);
898	                        if (!rechecked) {
899	                            rechecked = true;
900	                            if (rechecks == null) {
901	                                rechecks = new ArrayList<StaticParam>();
902	                            }
903	                            rechecks.add(sp);
904	                        }
905	                    }
906	                }
907	            } else if (DUMP_INFERENCE) System.err.println("Non-simple StaticParam " + sp);
908	        }
909	        /* FIX FOR #62 */
910	        if (params.size() == 1 && args.size() != 1) {
911	            Iterator<Param> pit = params.iterator();
912	            Param pa = pit.next();
913	
914	            if (!NodeUtil.isVarargsParam(pa)) {
915	                /* Tuple (or even re-tuple) arguments when inferring type
916	                 * if passing different # of args to 1-arg function. */
917	                if (DUMP_INFERENCE) {
918	                    System.err.println("Tupling args to match single-arg context.");
919	                }
